--
-- Name: check_membership_assignment_roles(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_membership_assignment_roles() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    assigned_role_id UUID;
BEGIN
    -- A manager must be assigned to an admin.
    IF NEW.admin_membership_id IS NOT NULL THEN
        SELECT role_id
        INTO assigned_role_id
        FROM memberships
        WHERE id = NEW.admin_membership_id
          AND organization_id = NEW.organization_id;

        IF assigned_role_id IS DISTINCT FROM
           '00000000-0000-0000-0000-000000000002'::UUID
        THEN
            RAISE EXCEPTION
                'admin_membership_id must reference an admin membership';
        END IF;
    END IF;

    -- A member must be assigned to a manager.
    IF NEW.manager_membership_id IS NOT NULL THEN
        SELECT role_id
        INTO assigned_role_id
        FROM memberships
        WHERE id = NEW.manager_membership_id
          AND organization_id = NEW.organization_id;

        IF assigned_role_id IS DISTINCT FROM
           '00000000-0000-0000-0000-000000000003'::UUID
        THEN
            RAISE EXCEPTION
                'manager_membership_id must reference a manager membership';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_membership_assignment_roles() OWNER TO postgres;

--
-- Name: check_membership_referenced_role(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_membership_referenced_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- A membership referenced as an admin must remain an admin.
    IF NEW.role_id IS DISTINCT FROM OLD.role_id
       AND EXISTS (
           SELECT 1
           FROM memberships
           WHERE admin_membership_id = NEW.id
             AND organization_id = NEW.organization_id
       )
       AND NEW.role_id <> '00000000-0000-0000-0000-000000000002'::UUID
    THEN
        RAISE EXCEPTION
            'Cannot change role: membership is assigned as an admin';
    END IF;

    -- A membership referenced as a manager must remain a manager.
    IF NEW.role_id IS DISTINCT FROM OLD.role_id
       AND EXISTS (
           SELECT 1
           FROM memberships
           WHERE manager_membership_id = NEW.id
             AND organization_id = NEW.organization_id
       )
       AND NEW.role_id <> '00000000-0000-0000-0000-000000000003'::UUID
    THEN
        RAISE EXCEPTION
            'Cannot change role: membership is assigned as a manager';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_membership_referenced_role() OWNER TO postgres;

--
-- Name: prevent_audit_log_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_audit_log_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Audit logs are append-only';
    END IF;

    IF
        NEW.id IS DISTINCT FROM OLD.id
        OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
        OR NEW.action IS DISTINCT FROM OLD.action
        OR NEW.result IS DISTINCT FROM OLD.result
        OR NEW.target_type IS DISTINCT FROM OLD.target_type
        OR NEW.target_id IS DISTINCT FROM OLD.target_id
        OR NEW.metadata IS DISTINCT FROM OLD.metadata
        OR NEW.created_at IS DISTINCT FROM OLD.created_at
        OR (
            NEW.actor_user_id IS NOT NULL
            AND NEW.actor_user_id IS DISTINCT FROM OLD.actor_user_id
        )
        OR (
            NEW.actor_membership_id IS NOT NULL
            AND NEW.actor_membership_id IS DISTINCT FROM OLD.actor_membership_id
        )
    THEN
        RAISE EXCEPTION 'Audit logs are append-only';
    END IF;

    RETURN NEW;
END;
$$;


